<div class="page-title"><div><em>PROFILE</em><h1>Settings</h1><p>Manage your personal details, notifications, security and region.</p></div></div><div class="grid settings-grid"><nav class="panel settings-nav"><a class="active" data-tab="personal">♙ Personal information</a><a data-tab="notifications">♢ Notifications</a><a data-tab="security">✓ Security &amp; login</a><a data-tab="region">◎ Language &amp; region</a></nav><section class="panel settings-form"><div class="tab active" data-panel="personal"><h2>Personal information</h2><p>Keep your contact information up to date.</p><?=form_open_multipart('settings')?><div class="profile-row"><?php if(!empty($profile['avatar_path'])):?><img class="avatar big avatar-image" src="<?=base_url($profile['avatar_path'])?>" alt="Profile photo"><?php else:?><span class="avatar big"><?=initials($profile['first_name'].' '.$profile['last_name'])?></span><?php endif?><div><b>Profile photo</b><small>JPG, PNG or WebP, up to <?=number_format($this->config->item('max_upload_kb')/1024,0)?>MB</small></div><label class="outline file-button">Change photo<input type="file" name="avatar" accept="image/jpeg,image/png,image/webp"></label></div><div class="kyc-status"><span class="kyc-badge kyc-<?=html_escape($profile['kyc_status']??'pending')?>"><?=ucfirst($profile['kyc_status']??'pending')?></span><div><b>Identity verification</b><small><?=($profile['kyc_status']??'pending')==='verified'?'Your identity has been verified.':'Your identity verification is '.($profile['kyc_status']??'pending').'.'?></small></div></div><div class="form-grid"><div><label>First name</label><input name="first_name" value="<?=html_escape($profile['first_name'])?>" required></div><div><label>Last name</label><input name="last_name" value="<?=html_escape($profile['last_name'])?>" required></div><div><label>Email address</label><input name="email" type="email" value="<?=html_escape($profile['email'])?>" required></div><div><label>Phone number</label><input name="phone" value="<?=html_escape($profile['phone'])?>"></div><div><label>City</label><input name="city" value="<?=html_escape($profile['city'])?>"></div><div><label>Country</label><input name="country" value="<?=html_escape($profile['country'])?>"></div></div><label>Home address</label><input name="address" value="<?=html_escape($profile['address'])?>"><button class="btn">Save changes</button></form></div>
<div class="tab" data-panel="notifications"><h2>Notifications</h2><p>Choose which updates you'd like to receive.</p><?=form_open('settings/preferences')?><?php $pref=function($k)use($preferences){return isset($preferences[$k])&&$preferences[$k];};?><label class="pref-row"><span><b>Transfers</b><small>Alert me when money leaves or arrives</small></span><input type="hidden" name="notify_transfers" value=""><input type="checkbox" name="notify_transfers" value="1" <?=$pref('notify_transfers')?'checked':''?>></label><label class="pref-row"><span><b>Support requests</b><small>Notify me of replies to my tickets</small></span><input type="hidden" name="notify_tickets" value=""><input type="checkbox" name="notify_tickets" value="1" <?=$pref('notify_tickets')?'checked':''?>></label><label class="pref-row"><span><b>Security alerts</b><small>Login and security activity alerts</small></span><input type="hidden" name="notify_security" value=""><input type="checkbox" name="notify_security" value="1" <?=$pref('notify_security')?'checked':''?>></label><label class="pref-row"><span><b>Email alerts</b><small>Receive notifications by email</small></span><input type="hidden" name="email_alerts" value=""><input type="checkbox" name="email_alerts" value="1" <?=$pref('email_alerts')?'checked':''?>></label><button class="btn">Save preferences</button></form></div>
<div class="tab" data-panel="security"><h2>Security &amp; login</h2><p>Change your password and manage two-factor authentication.</p><?=form_open('settings/password')?><label>Current password</label><input name="current_password" type="password" required autocomplete="current-password"><div class="form-grid"><div><label>New password</label><input name="new_password" type="password" required minlength="8" autocomplete="new-password"></div><div><label>Confirm new password</label><input name="confirm_new" type="password" required autocomplete="new-password"></div></div><button class="btn">Update password</button></form><h2 style="margin-top:26px">Two-factor authentication</h2><p>Add an extra layer of security. When enabled, a one-time code is required at sign-in.</p><?=form_open('settings/twofa')?><label class="pref-row"><span><b>Require a sign-in code (2FA)</b><small>We'll email a 6-digit code on every sign-in</small></span><input type="hidden" name="twofa_enabled" value="0"><input type="checkbox" name="twofa_enabled" value="1" <?=(!empty($profile['twofa_enabled']))?'checked':''?> onchange="this.form.submit()"></label></form><div class="profile-row"><i class="secure-badge">✓</i><div><b>Secure session</b><small>Last login: <?=html_escape($profile['last_login_at']??'—')?> · IP <?=html_escape($profile['last_login_ip']??'—')?></small></div></div></div>
<div class="tab" data-panel="region"><h2>Language &amp; region</h2><p>Set your preferred language and region.</p><?=form_open('settings/preferences')?><div class="form-grid"><div><label>Language</label><select name="language"><option value="en" <?=($preferences['language']??'en')==='en'?'selected':''?>>English</option><option value="de" <?=($preferences['language']??'')==='de'?'selected':''?>>Deutsch</option><option value="fr" <?=($preferences['language']??'')==='fr'?'selected':''?>>Français</option></select></div><div><label>Region</label><select name="region"><option value="CH" <?=($preferences['region']??'CH')==='CH'?'selected':''?>>Switzerland (CH)</option><option value="US" <?=($preferences['region']??'')==='US'?'selected':''?>>United States (US)</option><option value="UK" <?=($preferences['region']??'')==='UK'?'selected':''?>>United Kingdom (UK)</option><option value="EU" <?=($preferences['region']??'')==='EU'?'selected':''?>>European Union (EU)</option></select></div></div><button class="btn">Save preferences</button></form></div>
</section></div>
<script>document.querySelectorAll('[data-tab]').forEach(function(t){t.addEventListener('click',function(){document.querySelectorAll('[data-tab]').forEach(function(x){x.classList.toggle('active',x===t)});document.querySelectorAll('[data-panel]').forEach(function(p){p.classList.toggle('active',p.getAttribute('data-panel')===t.getAttribute('data-tab'))})})});</script>
